import test from 'node:test';import assert from 'node:assert/strict';import {correctProductData} from './product-title-corrections.mjs';
test('triagem102 qualifica ofertas sem alterar operação',()=>{for(const [id,titulo,expected] of [["mlMLB4953439757","Kit Mobilador Teclado Gamer Rgb 80% Suporte Mouse Hub Cabo","Kit Mobilador Teclado Gamer Rgb 80% Suporte Mouse Hub Cabo"],["mlMLB4964975723","Google Gemini Ai Pro 18 Meses | Via Link De Ativação","Google AI Pro — oferta de terceiro anuncia 18 meses"],["mlMLB5136589984","Tenis Masculino Sapatenis Polo Feet Sapato Casual Promoção","Tenis Masculino Sapatenis Polo Feet Sapato Casual Promoção"]]){const p={id,titulo,comentario:'anterior',preco:'preservar',linkAfiliado:'https://meli.la/preservar'},x=correctProductData(p);assert.notEqual(x.comentario,p.comentario);assert.equal(x.preco,p.preco);assert.equal(x.linkAfiliado,p.linkAfiliado);assert.equal(x.titulo,expected);assert.deepEqual(correctProductData(x),x);}});
